  ["item.gold-comb-shaped-like-a-dragon-with-red-garnets-as-eyes.xdmg2024"]={title="Gold comb shaped like a dragon with red garnets as eyes",subtitle="Item - XDMG - 2024",body="Pagina: 215\n\nRaridade: none"},
